draw:
var av=15.75, as_=17.8, ac=0.711, asym=23.7;
function pair(A,Z){ var N=A-Z; if(Z%2===0&&N%2===0) return 12/Math.sqrt(A); if(Z%2===1&&N%2===1) return -12/Math.sqrt(A); return 0; }
var Z=Math.round(p.Z), N=Math.round(p.N), A=Z+N;
var B = av*A - as_*Math.pow(A,2/3) - ac*Z*(Z-1)/Math.pow(A,1/3) - asym*(A-2*Z)*(A-2*Z)/A + pair(A,Z);
if(B<0) B=0;
var mH=1.007825, mn=1.008665;
var parts = Z*mH + N*mn;
var mass = parts - B/931.5;

ctx.font="12px ui-sans-serif, system-ui, sans-serif";
var padT=26, padB=42;
var base=H-padB;
var top=padT;
var scale=(base-top)/parts;
var wBar=Math.min(90,(W-140)/2);
var x1=W*0.24-wBar/2, x2=W*0.68-wBar/2;

ctx.fillStyle=C.faint;
ctx.fillRect(x1, base-parts*scale, wBar, parts*scale);
ctx.strokeStyle=C.rule; ctx.lineWidth=1;
ctx.strokeRect(x1, base-parts*scale, wBar, parts*scale);

ctx.fillStyle=C.accent;
ctx.fillRect(x2, base-mass*scale, wBar, mass*scale);
ctx.strokeRect(x2, base-mass*scale, wBar, mass*scale);

ctx.strokeStyle=C.ink; ctx.setLineDash([3,4]);
ctx.beginPath(); ctx.moveTo(x1, base-parts*scale); ctx.lineTo(x2+wBar+22, base-parts*scale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x2, base-mass*scale); ctx.lineTo(x2+wBar+22, base-mass*scale); ctx.stroke();
ctx.setLineDash([]);

var ax=x2+wBar+14;
ctx.strokeStyle=C.ink; ctx.lineWidth=1.5;
ctx.beginPath(); ctx.moveTo(ax, base-parts*scale); ctx.lineTo(ax, base-mass*scale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax-4, base-parts*scale+6); ctx.lineTo(ax, base-parts*scale); ctx.lineTo(ax+4, base-parts*scale+6); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax-4, base-mass*scale-6); ctx.lineTo(ax, base-mass*scale); ctx.lineTo(ax+4, base-mass*scale-6); ctx.stroke();

ctx.fillStyle=C.ink; ctx.textAlign="center";
ctx.fillText("mass defect", (ax+W)/2 - 6, base-(parts+mass)*scale/2 - 2);
ctx.fillStyle=C.figure;
ctx.fillText("= B / 931.5", (ax+W)/2 - 6, base-(parts+mass)*scale/2 + 13);

ctx.fillStyle=C.figure; ctx.textAlign="center";
ctx.fillText(Z+" free protons +", x1+wBar/2, base+16);
ctx.fillText(N+" free neutrons", x1+wBar/2, base+30);
ctx.fillText("the bound nucleus", x2+wBar/2, base+16);
ctx.fillText("A = "+A, x2+wBar/2, base+30);
ctx.fillStyle=C.ink;
ctx.fillText(parts.toFixed(4)+" u", x1+wBar/2, base-parts*scale-8);
ctx.fillText(mass.toFixed(4)+" u", x2+wBar/2, base-mass*scale-8);

out.note = "defect "+(parts-mass).toFixed(4)+" u × 931.5 = B "+B.toFixed(1)+" MeV, so B/A = "+(B/A).toFixed(2)+" MeV per nucleon";
